package com.smartproperty.platform.residentportal.service.impl;
import com.smartproperty.platform.access.*;import com.smartproperty.platform.auth.context.*;import com.smartproperty.platform.common.exception.BusinessException;import com.smartproperty.platform.residentportal.dto.*;import com.smartproperty.platform.residentportal.mapper.ResidentPortalMapper;import com.smartproperty.platform.residentportal.service.ResidentPortalService;import com.smartproperty.platform.residentportal.vo.ResidentPortalVO.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ResidentPortalServiceImpl implements ResidentPortalService {private final ResidentPortalMapper mapper;private final ActorContextProvider actorProvider;private final AuthorizationService authorization;private final DataScopeService scope;public ResidentPortalServiceImpl(ResidentPortalMapper m,ActorContextProvider a,AuthorizationService b,DataScopeService c){mapper=m;actorProvider=a;authorization=b;scope=c;}private Long person(){var a=actorProvider.currentActor();if(!a.hasRole("PERSON_USER")||a.personId()==null)throw new BusinessException(HttpStatus.FORBIDDEN,"RESIDENT_PORTAL_REQUIRED","当前账号不是已绑定居民账号");return a.personId();}public SummaryVO summary(){return mapper.selectSummary(person());}public List<ResidenceVO> residences(){return mapper.selectResidences(person());}public List<PropertyVO> properties(){return mapper.selectProperties(person());}public List<BillVO> bills(){return mapper.selectBills(person());}public List<NotificationVO> notifications(){return mapper.selectNotifications(person());}public List<IncidentVO> myIncidents(){return mapper.selectMyIncidents(person());}@Transactional public IncidentVO submitIncident(ResidentIncidentCreateRequest r){Long personId=person();if(!mapper.isCurrentResident(personId,r.propertyUnitId()))throw new BusinessException(HttpStatus.FORBIDDEN,"RESIDENCE_REQUIRED","只能为自己的当前居所提交异常上报");var c=new ResidentPortalMapper.IncidentCommand(r.propertyUnitId(),r.category(),r.description().trim());mapper.insertIncident(personId,c);return mapper.selectMyIncidents(personId).stream().filter(x->x.residentIncidentId().equals(c.getResidentIncidentId())).findFirst().orElseThrow();}public List<IncidentVO> scopedIncidents(){authorization.requirePermission(PermissionCodes.INCIDENT_VIEW);var s=scope.currentCommunityScope();return mapper.selectScopedIncidents(!s.global(),s.communityIds());}public void updateIncidentStatus(Long id,IncidentStatusRequest r){var actor=authorization.requirePermission(PermissionCodes.INCIDENT_MANAGE);Long property=mapper.selectIncidentProperty(id);if(property==null)throw new BusinessException(HttpStatus.NOT_FOUND,"INCIDENT_NOT_FOUND","未找到异常上报");scope.requireProperty(property);if(mapper.updateIncidentStatus(id,r.status(),actor.accountId())!=1)throw new BusinessException(HttpStatus.CONFLICT,"INCIDENT_STATE_CHANGED","上报状态已变化，请刷新后重试");}}
